// components/Header.js
"use client";

import Link from "next/link";
import Image from "next/image";
import { useAuth } from '@/app/hooks/useAuth';
import { useEffect, useState } from "react";

export default function Header() {
  const { logout, user, isLoading, error, isAuthenticated } = useAuth();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header className={`fixed w-full z-50 transition-all duration-300 ${
      isScrolled 
        ? 'bg-white/95 backdrop-blur-md shadow-lg py-2' 
        : 'bg-transparent py-4'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="shrink-0">
            <Link href="/" className="block" aria-label="Home">
              <Image
                src="/images/logoLight1.png"
                alt="Logo"
                width={isScrolled ? 180 : 200}
                height={isScrolled ? 60 : 70}
                priority={true}
                className="transition-all duration-300"
              />
            </Link>
          </div>

          {/* Desktop Navigation */}
          <nav className="hidden lg:flex items-center justify-between flex-1 ml-10">
            {/* Main Navigation Links */}
            <ul className="flex items-center space-x-1">
              {['Home', 'About','Request', 'Contact'].slice(0, user?.role === 'admin' ? 2 : 4).map((item) => (
                <li key={item}>
                  <Link
                    href={`/${item === 'Home' ? '' : item.toLowerCase()}`}
                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                      isScrolled 
                        ? 'text-gray-700 hover:text-primary hover:bg-gray-50' 
                        : 'text-white hover:text-primary hover:bg-white/10'
                    }`}
                  >
                    {item}
                  </Link>
                </li>
              ))}
            </ul>

            {/* User Actions Section */}
            <div className="flex items-center space-x-4">
              {isAuthenticated ? (
                <>
                  {/* User Greeting & Admin */}
                  <div className="flex items-center space-x-4">
                    <Link 
                      href="/profile" 
                      className={`flex items-center space-x-2 px-4 py-2 rounded-lg transition-all duration-200 ${
                        isScrolled 
                          ? 'text-gray-700 hover:bg-gray-50' 
                          : 'text-white hover:bg-white/10'
                      }`}
                    >
                      <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                        <span className="text-sm font-medium">
                          {user?.firstName?.charAt(0) || 'U'}
                        </span>
                      </div>
                      <span className="font-medium">
                        Hi, {user?.firstName || 'User'}!
                      </span>
                    </Link>

                    {user?.role === 'admin' && (
                      <Link
                        href="/adminboard"
                        className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                          isScrolled 
                            ? 'text-purple-600 hover:bg-purple-50' 
                            : 'text-purple-300 hover:bg-white/10'
                        }`}
                      >
                        Admin Dashboard
                      </Link>
                    )}
                  </div>

                  {/* Logout Button */}
                  <button
                    onClick={() => logout()}
                    className="px-4 py-2 bg-red-500 text-white rounded-lg font-medium hover:bg-red-600 transition-all duration-200 flex items-center space-x-2 shadow-sm hover:shadow-md"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                    <span>Logout</span>
                  </button>
                </>
              ) : (
                <>
                  {/* Login Button */}
                  <Link
                    href="/login"
                    className={`px-5 py-2.5 rounded-lg font-medium transition-all duration-200 border ${
                      isScrolled 
                        ? 'text-primary border-primary hover:bg-primary hover:text-white' 
                        : 'text-white border-white/50 hover:bg-white hover:text-primary'
                    }`}
                  >
                    Login
                  </Link>

                  {/* Register Button */}
                  {user?.role === 'student' &&
                  <Link
                  href="/register"
                  className="px-5 py-2.5 bg-linear-to-r from-primary to-green-500 text-white rounded-lg font-medium hover:shadow-lg transition-all duration-200 hover:from-primary/90 hover:to-green-500/90"
                  >
                    Send Request
                  </Link>
                  }
                </>
              )}
            </div>
          </nav>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className={`lg:hidden p-2 rounded-lg transition-all duration-200 ${
              isScrolled 
                ? 'text-gray-700 hover:bg-gray-100' 
                : 'text-white hover:bg-white/10'
            }`}
            aria-label="Toggle menu"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              {isMobileMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>

        {/* Mobile Menu Dropdown */}
        {isMobileMenuOpen && (
          <div className={`lg:hidden mt-4 pb-4 rounded-lg transition-all duration-200 ${
            isScrolled ? 'bg-white/95 backdrop-blur-md' : 'bg-gray-900/95 backdrop-blur-md'
          }`}>
            <div className="px-2 pt-2 pb-3 space-y-1">
              {/* Mobile Navigation Links */}
              {['Home', 'Requests', 'About', 'Contact'].map((item) => (
                <Link
                  key={item}
                  href={`/${item === 'Home' ? '' : item.toLowerCase()}`}
                  className={`block px-3 py-3 rounded-lg font-medium transition-all duration-200 ${
                    isScrolled 
                      ? 'text-gray-700 hover:text-primary hover:bg-gray-50' 
                      : 'text-white hover:text-primary hover:bg-white/10'
                  }`}
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item}
                </Link>
              ))}

              {/* Mobile User Actions */}
              <div className="border-t pt-3 mt-3 border-gray-700">
                {isAuthenticated ? (
                  <>
                    <Link
                      href="/profile"
                      className={`flex items-center space-x-3 px-3 py-3 rounded-lg transition-all duration-200 ${
                        isScrolled 
                          ? 'text-gray-700 hover:bg-gray-50' 
                          : 'text-white hover:bg-white/10'
                      }`}
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      <div className="w-10 h-10 rounded-full bg-primary/20 flex items-center justify-center">
                        <span className="font-medium">
                          {user?.firstName?.charAt(0) || 'U'}
                        </span>
                      </div>
                      <div>
                        <p className="font-medium">Hi, {user?.firstName || 'User'}!</p>
                        <p className="text-sm opacity-75">View Profile</p>
                      </div>
                    </Link>

                    {user?.role === 'admin' && (
                      <Link
                        href="/admin"
                        className={`block px-3 py-3 rounded-lg font-medium transition-all duration-200 ${
                          isScrolled 
                            ? 'text-purple-600 hover:bg-purple-50' 
                            : 'text-purple-300 hover:bg-white/10'
                        }`}
                        onClick={() => setIsMobileMenuOpen(false)}
                      >
                        Admin Dashboard
                      </Link>
                    )}

                    <button
                      onClick={() => {
                        logout();
                        setIsMobileMenuOpen(false);
                      }}
                      className="w-full mt-2 px-3 py-3 bg-red-500 text-white rounded-lg font-medium hover:bg-red-600 transition-all duration-200 flex items-center justify-center space-x-2"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                      </svg>
                      <span>Logout</span>
                    </button>
                  </>
                ) : (
                  <>
                    <Link
                      href="/login"
                      className={`block px-3 py-3 mb-2 rounded-lg font-medium transition-all duration-200 border ${
                        isScrolled 
                          ? 'text-primary border-primary hover:bg-primary hover:text-white' 
                          : 'text-white border-white/50 hover:bg-white hover:text-primary'
                      }`}
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      Login
                    </Link>
                    <Link
                      href="/register"
                      className="block px-3 py-3 bg-linear-to-r from-primary to-green-500 text-white rounded-lg font-medium hover:shadow-lg transition-all duration-200 text-center"
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      Send Request
                    </Link>
                  </>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
}